// Generated by AI (Claude) - reviewed and adapted by the HydroRush team.
using UnityEngine;


// Central audio hub (Singleton).
//Plays the looping background music and one-shot sound effects, and remembers the
// player's volume choices so a settings menu can change them.
// Use it from any script with: AudioManager.Instance.PlaySfx(clip);

public class AudioManager : MonoBehaviour
{
    // ---------------------------------------------------------------------
    // Singleton
    // ---------------------------------------------------------------------

    // The single shared instance. Null until the first AudioManager wakes up.
    public static AudioManager Instance { get; private set; }

    // PlayerPrefs keys used to remember the volume choices between sessions
    private const string MusicVolumeKey = "HydroRush.MusicVolume";
    private const string SfxVolumeKey = "HydroRush.SfxVolume";

    // ---------------------------------------------------------------------
    // Inspector fields
    // ---------------------------------------------------------------------

    [Header("Audio sources")]
    [SerializeField] private AudioSource musicSource;
    [SerializeField] private AudioSource sfxSource;

    [Header("Background music")]
    [SerializeField] private AudioClip backgroundMusic;
    [SerializeField] private bool playMusicOnStart = true;

    [Header("Default volumes (0 - 1)")]
    [SerializeField, Range(0f, 1f)] private float defaultMusicVolume = 0.6f;
    [SerializeField, Range(0f, 1f)] private float defaultSfxVolume = 1f;

    /// <summary>Current music volume (0 - 1).</summary>
    public float MusicVolume { get; private set; }

    /// <summary>Current sound effects volume (0 - 1).</summary>
    public float SfxVolume { get; private set; }

    // ---------------------------------------------------------------------
    // Unity lifecycle
    // ---------------------------------------------------------------------

    private void Awake()
    {
        // Singleton guard: if another AudioManager already exists, this duplicate removes itself.
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        Instance = this;
        DontDestroyOnLoad(gameObject); // keeps the music playing when the scene changes

        EnsureAudioSources();
        LoadVolumes();
    }

    private void Start()
    {
        // A destroyed duplicate can still reach Start in the same frame, so ignore it here
        if (Instance != this)
        {
            return;
        }

        if (playMusicOnStart && backgroundMusic != null)
        {
            PlayMusic(backgroundMusic);
        }
    }

    private void OnDestroy()
    {
        // Clear the static reference only if it points to this object
        if (Instance == this)
        {
            Instance = null;
        }
    }

   

    //Starts a music track. Does nothing if that same track is already playing.
    public void PlayMusic(AudioClip clip, bool loop = true)
    {
        if (clip == null)
        {
            return;
        }

        if (musicSource.clip == clip && musicSource.isPlaying)
        {
            return;
        }

        musicSource.clip = clip;
        musicSource.loop = loop;
        musicSource.Play();
    }

    /// <summary>Stops the current music track.</summary>
    public void StopMusic()
    {
        musicSource.Stop();
    }

    //Plays a sound effect once. volumeScale multiplies the global SFX volume.
    public void PlaySfx(AudioClip clip, float volumeScale = 1f)
    {
        if (clip == null)
        {
            return;
        }

        sfxSource.PlayOneShot(clip, volumeScale);
    }

    //Sets the music volume (0 - 1) and remembers it.
    public void SetMusicVolume(float volume)
    {
        MusicVolume = Mathf.Clamp01(volume);
        musicSource.volume = MusicVolume;
        PlayerPrefs.SetFloat(MusicVolumeKey, MusicVolume);
    }

    //Sets the sound effects volume (0 - 1) and remembers it.
    public void SetSfxVolume(float volume)
    {
        SfxVolume = Mathf.Clamp01(volume);
        sfxSource.volume = SfxVolume;
        PlayerPrefs.SetFloat(SfxVolumeKey, SfxVolume);
    }

    // ---------------------------------------------------------------------
    // Internal helpers
    // ---------------------------------------------------------------------

    //Creates the two AudioSources if they were not assigned, and configures them.
    private void EnsureAudioSources()
    {
        if (musicSource == null)
        {
            musicSource = gameObject.AddComponent<AudioSource>();
        }

        if (sfxSource == null)
        {
            sfxSource = gameObject.AddComponent<AudioSource>();
        }

        // Music: 2D sound that loops forever and never starts by itself
        musicSource.loop = true;
        musicSource.playOnAwake = false;
        musicSource.spatialBlend = 0f;

        // Effects: 2D one-shots
        sfxSource.loop = false;
        sfxSource.playOnAwake = false;
        sfxSource.spatialBlend = 0f;
    }

    //Reads the saved volumes (or the defaults) and applies them to the sources.
    private void LoadVolumes()
    {
        MusicVolume = PlayerPrefs.GetFloat(MusicVolumeKey, defaultMusicVolume);
        SfxVolume = PlayerPrefs.GetFloat(SfxVolumeKey, defaultSfxVolume);

        musicSource.volume = MusicVolume;
        sfxSource.volume = SfxVolume;
    }
}
